from pathlib import Path
from typing import Any, Dict, List, Optional

# Sensitive configuration must be loaded from environment variables
# Do not hardcode secrets. The script expects OKR_API_KEY and OKR_API_URL.
OKR_API_KEY = os.getenv("OKR_API_KEY", "")
OKR_API_URL = os.getenv("OKR_API_URL", "https://frvezdff.pythonanywhere.com/getrnr")

OKR_TEMPLATES = {
    "growth": {
